let selectedResource='metal',showFuture=false,researchMode='available';
function basicIndustry(){return ['drill','forest','crystal'].reduce((n,k)=>n+(state.m[k]||0),0)>=3||state.tech.length>0||state.stage>0}
function learned(id){return !id||(state.wonders||[]).includes(id)}
function stationOnline(){return state.megas.includes('wonder')}
function machineReady(m){return state.stage>=m.stage&&has(m.tech)&&learned(m.wonder)&&(!m.station||stationOnline())&&(!['solar','lab'].includes(m.id)||basicIndustry())}
unlocked=function(k){if(!R[k]||state.stage<R[k][3])return false;if(k==='science')return basicIndustry();if(k==='fragments')return learned('collector');if(k==='insight')return stationOnline();return !resourceGates[k]||has(resourceGates[k])};
function megaReady(m){return state.stage>=m.stage&&has(m.tech)&&learned(m.wonder)}
function inputEfficiency(){return learned('reclamation')?.8:1}
function powerEfficiency(){return learned('transmission')?.75:1}
function resourceMultiplier(k){return globalBoost()*boost(k==='science'||k==='insight'?'Research':k==='fuel'?'Propulsion':'Industry')*Math.pow(1.25,state.upgrades[k]||0)*(learned('stellarYield')&&!['science','insight','fuel'].includes(k)?1.5:1)*(k==='plasma'&&learned('plasmaWeave')?2:1)}
function migrate(s){if(!s||typeof s!=='object')return s;if(s.v===1){s={...s,r:{...Object.fromEntries(Object.keys(R).map(k=>[k,0])),...s.r},wonders:[],upgrades:{},theme:'aurora',survey:null,insightTotal:0,v:2};let old=s.tech||[];if(old.includes('dyson'))s.wonders.push('collector','ringDesign','swarmDesign','sphereDesign');if(old.includes('blackhole'))s.wonders.push('penroseDesign');if(old.includes('cosmic'))s.wonders.push('vacuumDesign');s.tech=old.filter(id=>!['dyson','wonder','blackhole','cosmic'].includes(id));if(old.includes('wonder')&&!s.tech.includes('stationSystems'))s.tech.push('stationSystems');if(old.includes('industry'))s.tech.push('electronics');if((s.m.extract7||0)>0){s.m={...s.m,plasmaReactor:(s.m.plasmaReactor||0)+s.m.extract7};delete s.m.extract7;s.tech.push('plasma')}if((s.m.extract8||0)>0){s.m={...s.m,accelerator:(s.m.accelerator||0)+s.m.extract8};delete s.m.extract8;s.tech.push('antimatter')}s.tech=[...new Set(s.tech)];}return s}
// Separate wonder insight from ordinary research. A station and a Sol survey are required.
function studyWonder(id){let w=wonders.find(w=>w.id===id);if(!w||learned(id)||!stationOnline()||state.stage<w.stage||!w.pre.every(learned)||!pay({insight:w.cost}))return;state.wonders.push(id);log('Wonder learned: '+w.name);toast(w.name+' discovered');render();save()}
function beginSurvey(){if(!stationOnline()||state.survey||!pay({science:50000,fuel:10000}))return;state.survey={left:60,total:60};log('Sol survey launched: reading the architecture of a star.');render();save()}
function upgradeCost(k){let n=state.upgrades[k]||0;return{science:75*Math.pow(2.5,n),[k]:100*Math.pow(2,n)}}
function upgradeResource(k){if(!unlocked(k)||['science','insight','fuel','fragments'].includes(k)||(state.upgrades[k]||0)>=10||!pay(upgradeCost(k)))return;state.upgrades[k]=(state.upgrades[k]||0)+1;toast(R[k][0]+' production increased by 25%');render();save()}
function applyTheme(){const t=themes[state.theme]||themes.aurora;for(const[k,v]of Object.entries({bg:t.bg,panel:t.panel,line:t.line,muted:t.muted,ink:t.ink,green:t.accent,blue:t.blue,orange:t.orange}))document.documentElement.style.setProperty('--'+k,v);document.documentElement.dataset.theme=state.theme}
function setTheme(key){if(!themes[key])return;state.theme=key;applyTheme();save();render()}
