if(id===10){x=w*.55;r=Math.min(w*.3,h*.38);c.save();c.translate(x,y);c.rotate(-.2);glow(0,0,r*1.25,'#56929d19');c.strokeStyle='#4c697b';c.lineWidth=2;c.beginPath();c.ellipse(0,0,r*.83,r*.43,0,0,Math.PI*2);c.stroke();c.strokeStyle='#b5c6ca';c.lineWidth=6;c.beginPath();c.ellipse(0,0,r*.79,r*.4,0,0,Math.PI*2);c.stroke();c.strokeStyle='#76c7c5';c.lineWidth=1;c.beginPath();c.ellipse(0,0,r*.84,r*.44,0,0,Math.PI*2);c.stroke();for(let a=0;a<Math.PI*2;a+=Math.PI/3){c.save();c.rotate(a);c.fillStyle='#7c949f';c.fillRect(0,-3,r*.8,6);c.fillStyle='#143a54';c.strokeStyle='#79a8c2';c.lineWidth=.6;for(let k=0;k<5;k++){c.fillRect(r*.35+k*9,-r*.25,7,r*.19);c.strokeRect(r*.35+k*9,-r*.25,7,r*.19);c.fillRect(r*.35+k*9,r*.07,7,r*.19);c.strokeRect(r*.35+k*9,r*.07,7,r*.19)}disk(r*.8,0,3,'#b1f3d0');c.restore()}let g=c.createLinearGradient(-15,-20,15,20);g.addColorStop(0,'#e0e7df');g.addColorStop(1,'#365265');c.fillStyle=g;c.beginPath();for(let j=0;j<6;j++){let a=j*Math.PI/3;c.lineTo(Math.cos(a)*18,Math.sin(a)*18)}c.closePath();c.fill();disk(0,0,7,'#83dbd0');glow(0,0,16,'#9cffff50');c.restore();return}
