if(id===13){c.save();c.translate(x,y);c.rotate(-.15);glow(0,0,r*1.5,'#d77d412b');for(let j=0;j<65;j++){let rr=r*(.65+j*.018);c.strokeStyle=`rgba(247,${130+j},${60+j},${.12+(.5-j/130)*.6})`;c.lineWidth=.9;c.beginPath();c.ellipse(0,0,rr,rr*.27,0,0,Math.PI*2);c.stroke()}glow(0,0,r*.78,'#f9bb6c88');disk(0,0,r*.54,'#020408');c.strokeStyle='#ffd8a5';c.lineWidth=2;c.beginPath();c.arc(0,0,r*.57,Math.PI,Math.PI*2);c.stroke();c.strokeStyle='#ffdfafaa';c.lineWidth=2.4;c.beginPath();c.ellipse(0,r*.05,r*1.4,r*.16,0,0,Math.PI);c.stroke();c.restore();return}
