function rings(front){c.save();c.translate(x,y);c.rotate(id===7?-1.15:-.3);let start=front?0:Math.PI,end=front?Math.PI:Math.PI*2;for(let j=0;j<(id===7?9:48);j++){let rr=r*(id===7?1.28+j*.016:1.28+j*.014);c.strokeStyle=id===7?`rgba(167,215,220,${.12+j*.018})`:j>25&&j<29?'#080e17':`rgba(${190+j%7*5},${171+j%5*7},${132+j%3*10},${.35+rnd()*.3})`;c.lineWidth=1.15;c.beginPath();c.ellipse(0,0,rr,rr*.37,0,start,end);c.stroke()}c.restore()}
if(id===6||id===7)rings(false);
glow(x,y,r*1.12,id===0?'#65bde332':id===7?'#7bc5cc22':id===8?'#5474e82b':'#ffffff08');c.save();c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.clip();const colors=[['#4599c7','#123956'],['#aeb0b3','#55595f'],['#ac9681','#4f433a'],['#e5c381','#93612f'],['#d78b68','#763e32'],['#dec7a8','#98735b'],['#ead8ac','#9a8666'],['#a1dcdb','#428b9c'],['#5389e4','#193d91']][id];let base=c.createRadialGradient(x-r*.45,y-r*.4,0,x+r*.2,y+r*.2,r*1.5);base.addColorStop(0,colors[0]);base.addColorStop(1,colors[1]);c.fillStyle=base;c.fillRect(x-r,y-r,r*2,r*2);
if(id===0){let polygons=[[[-.95,-.35],[-.7,-.72],[-.45,-.79],[-.29,-.61],[-.35,-.4],[-.13,-.27],[-.28,-.07],[-.46,-.16],[-.58,-.06],[-.71,-.28]],[[-.42,-.05],[-.15,.03],[-.01,.21],[-.15,.42],[-.25,.78],[-.38,.89],[-.43,.51],[-.57,.19]],[[.06,-.52],[.23,-.66],[.46,-.54],[.63,-.69],[.97,-.43],[.83,-.17],[.6,-.23],[.53,.04],[.36,-.03],[.3,-.24],[.09,-.29]],[[.07,-.2],[.35,-.2],[.52,.07],[.36,.43],[.23,.6],[.1,.33],[-.04,.04]],[[.64,.41],[.91,.33],[1,.55],[.78,.66],[.62,.59]]];for(const pts of polygons){c.fillStyle='#729575';c.beginPath();pts.forEach(([px,py])=>c.lineTo(x+px*r,y+py*r));c.closePath();c.fill()}ellipse(x,y-r*.98,r*.7,r*.13,'#ecf5edbb');for(let j=0;j<28;j++){let yy=y+(rnd()-.5)*r*1.8,xx=x+(rnd()-.5)*r*1.7;c.strokeStyle='#f1f5e746';c.lineWidth=1+rnd()*3;c.beginPath();c.ellipse(xx,yy,r*(.08+rnd()*.28),r*.035,-.17,0,Math.PI*1.6);c.stroke()}}
if(id===1||id===2){for(let j=0;j<110;j++){let px=x+(rnd()-.5)*r*2,py=y+(rnd()-.5)*r*2,rr=r*(.012+rnd()*.095);disk(px,py,rr,id===1?'#474d552f':'#44382a40');c.strokeStyle=id===1?'#e0e4e539':'#dfc3a331';c.lineWidth=1;c.beginPath();c.arc(px,py,rr,-.2,Math.PI*.85);c.stroke();disk(px+rr*.2,py+rr*.2,rr*.7,'#0000000f')}if(id===1){ellipse(x-r*.2,y-r*.25,r*.3,r*.23,'#494e5835');ellipse(x+r*.25,y-r*.36,r*.2,r*.3,'#4e535b35')}else{c.strokeStyle='#d3ad7f46';c.lineWidth=1.5;for(let j=0;j<8;j++){c.beginPath();let yy=y-r+rnd()*r*2;c.moveTo(x-r,yy);for(let k=0;k<7;k++)c.lineTo(x-r+k*r/3,yy+Math.sin(k*2+j)*r*.09);c.stroke()}}}
