if(id===4){for(let j=0;j<75;j++){ellipse(x+(rnd()-.5)*r*2,y+(rnd()-.5)*r*2,rnd()*r*.12,rnd()*r*.06,j%2?'#a9563933':'#e5ac7a22',rnd())}ellipse(x,y-r*.99,r*.52,r*.15,'#e7ddd1');ellipse(x+r*.17,y+r*.95,r*.32,r*.09,'#d9d1c4');c.strokeStyle='#683e32';c.lineWidth=2.8;c.beginPath();c.moveTo(x-r*.65,y+r*.02);c.bezierCurveTo(x-r*.2,y-r*.15,x+r*.25,y+r*.13,x+r*.55,y-r*.05);c.stroke();disk(x-r*.4,y-r*.22,r*.11,'#b67155');disk(x-r*.4,y-r*.22,r*.04,'#724533')}
