if(id===7){c.save();c.translate(x,y);c.rotate(-1.15);for(let j=0;j<14;j++){c.fillStyle=j%2?'#d3f1df15':'#388eaa12';c.fillRect(-r,-r+j*r/7,r*2,r*.065)}c.restore()}
