let shade=c.createLinearGradient(x-r,y-r*.3,x+r,y+r*.1);shade.addColorStop(0,'#00000000');shade.addColorStop(.5,'#00000005');shade.addColorStop(.8,'#02081250');shade.addColorStop(1,'#02060ee8');c.fillStyle=shade;c.fillRect(x-r,y-r,r*2,r*2);c.restore();if(id===6||id===7)rings(true);
