drawSpace=function(){paintWorld(document.getElementById('space'),selectedWorld,true)};
function drawSol(){let cv=document.getElementById('sol-canvas');if(!cv)return;let d=Math.min(2,window.devicePixelRatio||1),w=cv.clientWidth,h=cv.clientHeight;cv.width=w*d;cv.height=h*d;const c=cv.getContext('2d');c.scale(d,d);c.fillStyle='#080e17';c.fillRect(0,0,w,h);let cx=w*.49,cy=h*.48,rx=Math.min(w*.43,h*.85),ry=rx*.4;for(let j=0;j<140;j++){let x=((j*7919)%1000)/1000*w,y=((j*5171)%1000)/1000*h;c.fillStyle='#aab9d346';c.fillRect(x,y,.8,.8)}let g=c.createRadialGradient(cx,cy,0,cx,cy,40);g.addColorStop(0,'#ffe7ab');g.addColorStop(.3,'#e9b26188');g.addColorStop(1,'#e9b26100');c.fillStyle=g;c.beginPath();c.arc(cx,cy,40,0,Math.PI*2);c.fill();c.fillStyle='#ffdda0';c.beginPath();c.arc(cx,cy,10,0,Math.PI*2);c.fill();c.font='10px system-ui';c.fillStyle='#d8c9ae';c.fillText('SOL',cx-10,cy+30);const order=[2,3,0,4,5,6,7,8];for(let j=0;j<order.length;j++){let id=order[j],a=j*.87-.8,scale=.18+j*.09;c.strokeStyle=id<=state.stage?'#7dbda047':'#647a9033';c.lineWidth=1;c.beginPath();c.ellipse(cx,cy,rx*scale,ry*scale,0,0,Math.PI*2);c.stroke();let px=cx+Math.cos(a)*rx*scale,py=cy+Math.sin(a)*ry*scale;c.fillStyle=worlds[id][2];c.beginPath();c.arc(px,py,id===5?6:4,0,Math.PI*2);c.fill();c.fillStyle=id<=state.stage?'#d8e3e2':'#8598aa';c.fillText(worlds[id][0],px+8,py-8)}for(let j=0;j<650;j++){let a=j*2.39996,scale=.94+((j*13)%100)/100*.1,px=cx+Math.cos(a)*rx*scale,py=cy+Math.sin(a)*ry*scale;c.fillStyle=j%4?'#9badc44a':'#dde2e68a';c.fillRect(px,py,1,1)}c.fillStyle='#92a3b7';c.fillText('KUIPER BELT',cx+rx*.63,cy+ry*.82);if(state.megas.some(id=>['ring','swarm','sphere'].includes(id))){c.strokeStyle='#edc77a';c.lineWidth=state.megas.includes('sphere')?7:2;c.setLineDash(state.megas.includes('swarm')?[2,3]:[]);c.beginPath();c.ellipse(cx,cy,24,17,0,0,Math.PI*2);c.stroke();c.setLineDash([])}if(stationOnline()){c.fillStyle='#a6efb1';c.fillRect(cx-rx*.9,cy-ry*.85,5,5);c.fillText('WONDER STATION',cx-rx*.9,cy-ry*.85-10)}}
function drawAllArt(){drawSpace();document.querySelectorAll('canvas[data-art]').forEach(cv=>paintWorld(cv,Number(cv.dataset.art)));drawSol()}

